using System.Security.Cryptography.X509Certificates;

namespace RSAReader.Research;

// Pinned LAWtrust CA certificates, published at https://www.lawtrust.co.za/repository/.
// Selected public certificates from LAWtrust's published CA repository. These
// permit an offline chain check only when all issuer certificates on the card's
// path are present. The observed cardholder certificates name DHA CA3 as issuer,
// which is not included here; their shared policy OID is not chain evidence.
// These are public CA certificates, not secrets: only their presence is trust-bearing.
// Regenerated from the repository DER files; see docs/lawtrust-anchors.md.
internal static class LawTrustAnchors
{
    // Self-signed roots used as the custom trust anchors.
    private static readonly string[] RootsB64 =
    {
        // RootCA01
        "",
        // RootCA02
        "",
    };

    // Published issuing CAs, supplied as chain-building material (ExtraStore).
    private static readonly string[] IntermediatesB64 =
    {
        // AATL_CA01
        "",
        // AUTH_CA01
        "",
        // AUTH_CA02
        "",
        // SECURE_CA01
        "",
        // SIGNING_CA01
        "",
        // AESIGN_CA1
        "",
        // AESIGN_CA2
        "",
    };

    private static X509Certificate2Collection Load(string[] bundle)
    {
        var certs = new X509Certificate2Collection();
        foreach (var b64 in bundle)
            certs.Add(X509CertificateLoader.LoadCertificate(Convert.FromBase64String(b64)));
        return certs;
    }

    public static X509Certificate2Collection Roots() => Load(RootsB64);
    public static X509Certificate2Collection Intermediates() => Load(IntermediatesB64);

    public static bool IsPinnedRoot(X509Certificate2 candidate)
    {
        foreach (var root in Roots())
            if (root.RawData.AsSpan().SequenceEqual(candidate.RawData)) return true;
        return false;
    }
}
